package com.meryem.aml.contracts.scoring;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/** Facts captured by the rule engine at scoring time, not generated by a language model. */
public record RuleHit(String code, int points, String ruleVersion, Map<String, Object> evidence) {
    public RuleHit {
        evidence = evidence == null ? Map.of()
                : Collections.unmodifiableMap(new LinkedHashMap<>(evidence));
    }
}
